async function fetchOfficeOpenXml(
  url: string,
  signal: AbortSignal,
  t: ReturnType<typeof useTranslation>['t'],
): Promise<ArrayBuffer> {
  const response = await fetch(url, {
    credentials: fileUrlCredentials(url),
    signal,
  });
  if (!response.ok) {
    throw new OfficeOpenXmlRequestError(
      t('files.previewRequestFailed', {
        defaultValue: `Preview request failed (${response.status}).`,
        status: response.status,
      }),
    );
  }
  return await response.arrayBuffer();
}

const upload = async (item: UploadItem): Promise<void> => {
  const controller = new AbortController();
  controllersRef.current.set(item.key, controller);
  setItems((current) =>
    current.map((candidate) =>
      candidate.key === item.key
        ? { ...candidate, status: 'uploading', controller, error: undefined }
        : candidate,
    ),
  );
  try {
    const { record } = await repository.uploadOne(
      { file: item.file },
      { signal: controller.signal },
    );
    controllersRef.current.delete(item.key);
    if (!mountedRef.current || controller.signal.aborted) return;
    setItems((current) =>
      current.filter((candidate) => candidate.key !== item.key),
    );
    commitCompletedRecord(record);
  } catch (error) {
    controllersRef.current.delete(item.key);
    if (
      controller.signal.aborted ||
      (error instanceof Error && error.name === 'AbortError')
    ) {
      if (mountedRef.current) {
        setItems((current) =>
          current.filter((candidate) => candidate.key !== item.key),
        );
      }
      return;
    }
    if (!mountedRef.current) return;
    const uploadError =
      error instanceof Error ? error : new Error('File upload failed.');
    setItems((current) =>
      current.map((candidate) =>
        candidate.key === item.key
          ? { ...candidate, error: uploadError, status: 'error' }
          : candidate,
      ),
    );
    onError?.(uploadError);
  }
};

export function resolveSafeFileUrl(
  value: string,
  trustedBlobUrls: ReadonlySet<string> = new Set(),
): string | undefined {
  const url = value.trim();
  if (!url) return undefined;
  if (trustedBlobUrls.has(url) && url.startsWith('blob:')) return url;
  try {
    const resolved = new URL(url, window.location.href);
    return resolved.protocol === 'http:' || resolved.protocol === 'https:'
      ? url
      : undefined;
  } catch {
    return undefined;
  }
}

export function fileUrlCredentials(url: string): RequestCredentials {
  return new URL(url, window.location.href).origin === window.location.origin
    ? 'same-origin'
    : 'omit';
}

